import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ---------- Elementwise add source ----------
elementwise_add_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

elementwise_add_cpp_source = 'torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);'

elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ---------- Matmul source ----------
matmul_cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(float* C, const float* A, const float* B, int M, int K, int N) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= M * N) return;
    int row = idx / N;
    int col = idx % N;
    float sum = 0.0f;
    for (int k = 0; k < K; ++k) {
        sum += A[k * M + row] * B[k * N + col];
    }
    C[idx] = sum;
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // A: (K, M), B: (K, N) -> output C: (M, N)
    int K = A.size(0);
    int M = A.size(1);
    int N = B.size(1);
    auto C = torch::empty({M, N}, device=A.device);
    int total = M * N;
    int block = 256;
    int num_blocks = (total + block - 1) / block;
    matmul_kernel<<<num_blocks, block>>>(
        C.data_ptr<float>(),
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        M, K, N
    );
    return C;
}
"""

matmul_cpp_source = 'torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);'

matmul_cuda = load_inline(
    name="matmul_cuda",
    cpp_sources=matmul_cpp_source,
    cuda_sources=matmul_cuda_source,
    functions=["matmul_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# Architecture‑specific dimensions
M = 2048  # 1024 * 2
K = 8192  # 4096 * 2
N = 4096  # 2048 * 2


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.matmul_cuda = matmul_cuda

    def forward(self, A, B):
        return self.matmul_cuda(A, B)
